// Asset module declarations (kept local so the project type-checks without vite/client).
declare module '*.webp' {
  const src: string;
  export default src;
}
declare module '*.avif' {
  const src: string;
  export default src;
}
declare module '*.jpg' {
  const src: string;
  export default src;
}
declare module '*.png' {
  const src: string;
  export default src;
}
declare module '*.bin' {
  const src: string;
  export default src;
}
declare module '*.css';
